class MemberEditFormScreen extends ConsumerStatefulWidget{ const MemberEditFormScreen({super.key,required this.familyId,this.memberId}); final String familyId; final String? memberId; @override ConsumerState<MemberEditFormScreen> createState()=>_S();} class _S extends ConsumerState<MemberEditFormScreen>{ final form=GlobalKey<FormState>(); final ctrls=<String,TextEditingController>{}; String? father,mother; @override Widget build(BuildContext context){ final fam=ref.watch(familyProvider(widget.familyId)).valueOrNull; final members=ref.watch(membersProvider(widget.familyId)).valueOrNull??[]; final existing=members.where((m)=>m.id==widget.memberId).firstOrNull; final schema=fam==null?null:ref.watch(schemaProvider(fam.fieldSchemaId)).valueOrNull; if(fam==null||schema==null)return const Scaffold(body:Center(child:CircularProgressIndicator())); for(final f in schema.fields){ctrls.putIfAbsent(f.key,()=>TextEditingController(text: existing?.data[f.key]?.toString()??''));} return Scaffold(appBar:AppBar(title:Text(existing==null?'Add member':'Edit member')), body:Form(key:form, child:ListView(padding:const EdgeInsets.all(16), children:[for(final f in schema.fields) if(f.key!='photo') Padding(padding:const EdgeInsets.only(bottom:12), child:DynamicFieldInput(field:f, controller:ctrls[f.key]!)), Autocomplete<FamilyMember>(displayStringForOption:(m)=>'${m.data['firstName']} ${m.data['lastName']}', optionsBuilder:(t)=>members.where((m)=>'${m.data['firstName']} ${m.data['lastName']}'.toLowerCase().contains(t.text.toLowerCase())), onSelected:(m)=>setState(()=>father=m.id), fieldViewBuilder:(c,tc,fn,sub)=>TextField(controller:tc, focusNode:fn, decoration: const InputDecoration(labelText:'Father autocomplete'))), if(father!=null) const Chip(label:Text('Link as father confirmed')), const SizedBox(height:8), Autocomplete<FamilyMember>(displayStringForOption:(m)=>'${m.data['firstName']} ${m.data['lastName']}', optionsBuilder:(t)=>members.where((m)=>'${m.data['firstName']} ${m.data['lastName']}'.toLowerCase().contains(t.text.toLowerCase())), onSelected:(m)=>setState(()=>mother=m.id), fieldViewBuilder:(c,tc,fn,sub)=>TextField(controller:tc, focusNode:fn, decoration: const InputDecoration(labelText:'Mother autocomplete'))), if(mother!=null) const Chip(label:Text('Link as mother confirmed')), FilledButton(onPressed:() async{ if(!form.currentState!.validate())return; final now=DateTime.now(); final id=existing?.id??const Uuid().v4(); final data={for(final e in ctrls.entries)e.key:e.value.text, 'photo': ctrls['photo']?.text.isNotEmpty==true?ctrls['photo']!.text:'https://i.pravatar.cc/300?u=$id'}; final member=FamilyMember(id:id,familyId:widget.familyId,schemaVersion:schema.version,data:data,photoMediaId:null,relations:(existing?.relations??const MemberRelations()).copyWith(fatherId: father, motherId: mother),createdBy:'mock-owner-user',lastEditedBy:'mock-owner-user',createdAt:existing?.createdAt??now,updatedAt:now); await ref.read(repositoryProvider).saveMember(member); if(context.mounted)context.go('/family/${widget.familyId}/member/$id');}, child:const Text('Save member'))])));}}
